args.command:
cd /tmp/probe_parse
q(){ cd /workspace; ./executable.orig "$@" >/tmp/probe_parse/o 2>/tmp/probe_parse/e; echo "[$*] exit=$? out=$(wc -c </tmp/probe_parse/o) :: $(head -c 90 /tmp/probe_parse/o | tr '\n' '|')"; }
for v in c c++ gnu c1 c12 c99x cc11 xc11 c11x gnu12 gnu99x c++99 c++1z c++2c c+++11 C11 gnu++2a posix; do q --std=$v t.c; done
